CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `vw_flpp_rejecteds` AS select `a`.`noflpp` AS `no_fl_pp`,`a`.`tgl_problem` AS `tgl_problem`,`z`.`nama_kary` AS `nama_kary`,`a`.`no_lots` AS `no_lots`,`s`.`no_lot_cust` AS `no_lot_cust`,`s`.`customer` AS `nm_customer`,`s`.`no_part` AS `no_brg_asli`,`s`.`nm_part` AS `nm_part`,`a`.`qty_problem` AS `qty_problem`,`q`.`nm_sequence` AS `nm_sequence`,`a`.`rank` AS `rank`,`x`.`nmproblem` AS `nmproblem`,`a`.`deskripsi_problem` AS `deskripsi_problem`,`a`.`analisa` AS `analisa`,`a`.`temp_action` AS `temp_action`,`a`.`fish_bone` AS `fish_bone`,`a`.`corrective_act` AS `corrective_act`,`a`.`pic` AS `pic`,`a`.`pic_dept` AS `pic_dept`,`a`.`judgment_level` AS `judgment_level`,`a`.`rank_a` AS `rank_a`,`a`.`pic_handler` AS `pic_handler`,`a`.`status_flpp` AS `status_flpp` from ((((`tblakakami` `a` left join (select `tbl_seq_all`.`no_lot` AS `no_lot`,`tbl_seq_all`.`no_lot_cust` AS `no_lot_cust`,`tbl_seq_all`.`customer` AS `customer`,`tbl_seq_all`.`no_part` AS `no_part`,`tbl_seq_all`.`nm_part` AS `nm_part` from `tbl_seq_all` group by `tbl_seq_all`.`no_lot`) `s` on(`a`.`no_lots` = `s`.`no_lot`)) left join `tblproblem` `x` on(`a`.`idproblems` = `x`.`idproblem`)) left join `tblkaryawan` `z` on(`a`.`pic` = `z`.`nik`)) left join `tblsequence` `q` on(`a`.`id_depts` = `q`.`id_seq`));

#
# Source for view vw_pic_approve
#

DROP VIEW IF EXISTS `vw_pic_approve`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `vw_pic_approve` AS select `p`.`nik` AS `nik`,`u`.`username` AS `user`,`p`.`jabatan` AS `jabatan`,`p`.`class` AS `class`,`p`.`email` AS `email` from (`tbl_pic_approve` `p` left join `tbl_user` `u` on(cast(`p`.`nik` as char charset utf8mb4) = cast(`u`.`id_user` as char charset utf8mb4)));

#
# Source for view vw_productivity_daily
#

DROP VIEW IF EXISTS `vw_productivity_daily`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `vw_productivity_daily` AS select `a`.`pic_01` AS `pic_01`,`a`.`id_seq` AS `id_seq`,`a`.`nm_seq` AS `nm_seq`,cast(`a`.`finish_time` as date) AS `tgl_selesai`,min(`a`.`start_time`) AS `start_time`,max(`a`.`finish_time`) AS `finish_time`,count(distinct `a`.`no_lot`) AS `total_lot`,round(coalesce(sum(`a`.`duration`),0),2) AS `menit_efektif`,round(avg(`d`.`cycle_time`),2) AS `target_cycle_time`,round(coalesce(sum(`a`.`duration`),0) / nullif(count(distinct `a`.`no_lot`),0),2) AS `actual_cycle_time`,round(avg(`d`.`cycle_time`) / nullif(coalesce(sum(`a`.`duration`),0) / nullif(count(distinct `a`.`no_lot`),0),0) * 100,2) AS `achievement_pct` from (`tbl_seq_all` `a` left join `tblsrp_detail` `d` on(`a`.`no_srp` = `d`.`no_srp` and `a`.`id_seq` = `d`.`id_sequence`)) where `a`.`finish` = 'yes' group by `a`.`pic_01`,`a`.`id_seq`,`a`.`nm_seq`,cast(`a`.`finish_time` as date);

#
# Source for view vw_productivity_operator
#

DROP VIEW IF EXISTS `vw_productivity_operator`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `vw_productivity_operator` AS select `a`.`pic_01` AS `pic_01`,`a`.`id_seq` AS `id_seq`,`a`.`nm_seq` AS `nm_seq`,min(`a`.`start_time`) AS `start_time`,max(`a`.`finish_time`) AS `finish_time`,count(distinct `a`.`no_lot`) AS `total_lot`,round(coalesce(sum(`a`.`duration`),0),2) AS `menit_efektif`,round(avg(`d`.`cycle_time`),2) AS `target_cycle_time`,round(coalesce(sum(`a`.`duration`),0) / nullif(count(distinct `a`.`no_lot`),0),2) AS `actual_cycle_time`,round(avg(`d`.`cycle_time`) / nullif(coalesce(sum(`a`.`duration`),0) / nullif(count(distinct `a`.`no_lot`),0),0) * 100,2) AS `achievement_pct` from (`tbl_seq_all` `a` left join `tblsrp_detail` `d` on(`a`.`no_srp` = `d`.`no_srp` and `a`.`id_seq` = `d`.`id_sequence`)) where `a`.`finish` = 'yes' group by `a`.`pic_01`,`a`.`id_seq`,`a`.`nm_seq`;

