CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `vw_rank_a` AS select `r`.`no_rank` AS `no_rank`,`r`.`noflpp` AS `noflpp`,`a`.`tgl_problem` AS `tgl_problem`,`r`.`tgl_pengajuan` AS `tgl_pengajuan`,`r`.`instruksi_perbaikan` AS `instruksi_perbaikan`,`r`.`link_ilustrasi` AS `link_ilustrasi`,`a`.`no_lots` AS `no_lots`,`s`.`no_part` AS `no_brg_asli`,`s`.`nm_part` AS `nm_part`,`s`.`customer` AS `nm_customer`,`a`.`qty_problem` AS `qty_problem`,`a`.`deskripsi_problem` AS `deskripsi_problem`,`r`.`status` AS `status` from ((`tblranka` `r` left join `tblakakami` `a` on(`r`.`noflpp` = `a`.`noflpp`)) left join (select `tbl_seq_all`.`no_lot` AS `no_lot`,`tbl_seq_all`.`no_part` AS `no_part`,`tbl_seq_all`.`nm_part` AS `nm_part`,`tbl_seq_all`.`customer` AS `customer` from `tbl_seq_all` group by `tbl_seq_all`.`no_lot`) `s` on(`a`.`no_lots` = `s`.`no_lot`));

